<script>
 import {getContext,onMount} from 'svelte';
 import {CONTEXT} from './context.js';
 import Button from '../components/Button.svelte';
 import Scope from './Scope.svelte';
 import Dialog from '../components/Dialog.svelte';
 const {options,shared}=getContext(CONTEXT),{insights,t,renderMarkdown,openBlock,repository}=options;
 let {viewId='default',memoId='',history=false,onback,onsettings,root}=$props();
 let observing=$state(false);
 let scope=$state({tag:'',start:'',end:''}),question=$state(''),snapshot=$state(null),result=$state(null),rows=$state([]),state=$state('preparing'),error=$state(''),scopeOpen=$state(false),preview=$state(false),serial=0,dead=false;
 const errorKeys={INSIGHT_MODEL_REQUIRED:'aiNotConfigured',NOTEBOOK_REQUIRED:'chooseNotebook',INSIGHT_BUSY:'insightBusy',INSIGHT_UNKNOWN_SOURCE:'insightSourcesInvalid',AI_NOT_CONFIGURED:'aiNotConfigured',INSIGHT_EMPTY:'insightEmpty',INSIGHT_TOO_LONG:'insightTooLong',INSIGHT_NO_TEXT:'insightEmpty',INSIGHT_INVALID_SOURCES:'insightSourcesInvalid',AI_BUSY:'insightBusy',INSIGHT_NOTEBOOK_REQUIRED:'chooseNotebook'};
 function fail(e){error=errorKeys[e.code]||'insightFailed';state='error';}
 async function prepare(){const token=++serial;state='preparing';error='';snapshot=null;try{const value=await insights.prepare({viewId,scope:{...scope},memoId,question,notebook:shared.settings.notebook});if(!dead&&token===serial){snapshot=value;state='ready';}}catch(e){if(!dead&&token===serial)fail(e);}}
 async function generate(){if(!snapshot||insights.busy)return;const token=++serial;state='generating';error='';try{const value=await insights.generate(Object.freeze({...snapshot,question}));if(!dead&&token===serial&&value){result=value;state='result';}}catch(e){if(!dead&&token===serial)fail(e);}}
 function cancel(){if(shared.insight?.phase==='saving')return;observing=false;serial++;insights.cancel();state=snapshot?'ready':'error';}
 export function leave(){if(shared.insight?.phase==='saving')return;if(state==='generating'&&!options.container.ownerDocument.defaultView.confirm(t('cancelInsightConfirm')))return;if(state==='generating')cancel();onback();}
 async function save(){state='saving';try{await insights.save(result);result={...result};}catch{error='insightSaveFailed';}finally{if(!dead)state='result';}}
 async function copy(){try{await options.container.ownerDocument.defaultView.navigator.clipboard.writeText(result.markdown);}catch{error='copyFailed';}}
 async function source(e){const a=e.target.closest('a');if(!a)return;const match=a.getAttribute('href')?.match(/^siyuan:\/\/blocks\/([\w-]+)$/);if(!match)return;e.preventDefault();try{if(await options.blockExists(match[1]))openBlock(match[1]);else error='sourceMissing';}catch{error='sourceMissing';}}
 $effect(()=>{const current=shared.insight;if(state==='generating'&&current?.phase==='cancelled'){serial++;state=snapshot?'ready':'error';observing=false;return;}if(!observing)return;if(current?.snapshot)snapshot=current.snapshot;if(current?.phase==='error'){error='insightFailed';state='error';observing=false;}else if(current?.result&&!current.busy){result=current.result;state='result';observing=false;}});
 onMount(()=>{if(insights.busy&&!history){snapshot=shared.insight?.snapshot||null;if(snapshot){viewId=snapshot.view.id;memoId=snapshot.memoId;question=snapshot.question;scope={...snapshot.scope};}observing=true;state='generating';}else if(history){insights.history().then(value=>{if(!dead){rows=value;state='history';}}).catch(e=>{if(!dead)fail(e);});}else prepare();return()=>{dead=true;serial++;if(state==='generating')insights.cancel();};});
</script>
<section class="qm-review qm-insights" data-state={state}>
 <header class="qm-review-header"><Button label={t('back')} icon="close" disabled={shared.insight?.phase==='saving'} onclick={leave}/><strong>{history?t('insightHistory'):(snapshot?.view.title||t('view_'+viewId))}</strong></header>
 {#if history}{#each rows as row}<Button label={row.title} class="qm-insight-history" onclick={()=>openBlock(row.id)}><strong>{row.title}</strong><small>{t('view_'+row.viewId)} · {row.created}</small></Button>{/each}{#if state==='history'&&!rows.length}<p>{t('insightHistoryEmpty')}</p>{/if}
 {:else if result}<div class="qm-insight-section"><p>{result.snapshot.view.title} · {t('scopeCount',{count:result.snapshot.sentCount})} · {result.created}</p>{#if result.saveError||(!result.id&&state!=='saving')}<p role="alert">{t('insightSaveFailed')}</p><Button label={t('retrySave')} onclick={save}/>{/if}
 <!-- svelte-ignore a11y_no_static_element_interactions, a11y_click_events_have_key_events -->
 <div class="qm-body qm-insight-body" onclick={source}>{@html renderMarkdown(result.markdown)}</div><p>{t('aiDisclaimer')}</p></div><div class="qm-insight-actions"><Button label={t('openNative')} disabled={!result.id} onclick={()=>openBlock(result.id)}/><Button label={t('copyResult')} onclick={copy}/><Button label={t('againInsight')} onclick={()=>{result=null;prepare();}}/></div>
 {:else}<div class="qm-insight-section"><p>{memoId?t('scopeSingle'):scope.tag?'#'+scope.tag:t('scopeAll')} · {scope.start||t('unlimited')} — {scope.end||t('unlimited')}</p>{#if !memoId}<Button label={t('adjustScope')} disabled={state==='generating'} onclick={()=>scopeOpen=true}/>{/if}</div>
 {#if snapshot}<div class="qm-insight-section"><p>{t('matchedCount',{count:snapshot.matchedCount})}</p><p>{t('sentCount',{count:snapshot.sentCount,chars:snapshot.charCount})}</p><p>{snapshot.dateStart} — {snapshot.dateEnd}</p>{#if snapshot.omittedCount}<p>{t('omittedCount',{count:snapshot.omittedCount})}</p>{/if}<Button label={t('previewMaterials')} aria-expanded={preview} onclick={()=>preview=!preview}/>{#if preview}{#each snapshot.items as item}<div class="qm-material"><time>{item.created}</time><p>{item.text}</p></div>{/each}{/if}</div>{/if}
 <label class="qm-insight-section">{t('insightQuestion')}<textarea rows="3" bind:value={question} disabled={state==='generating'} placeholder={t('question_'+viewId)}></textarea></label>
 {#if snapshot}<p class="qm-insight-explanation">{t('aiExternal',{model:typeof snapshot.model==='string'?snapshot.model:snapshot.model?.name||snapshot.model?.model||''})}</p>{/if}
 {#if state==='generating'}<div role="status">{t('insightPhase_'+(shared.insight?.phase||'generating'))}{#if shared.insight?.phase!=='saving'}<Button label={t('cancel')} onclick={cancel}/>{/if}</div>{:else if state==='preparing'}<p role="status">{t('insightPhase_preparing')}</p>{:else}<Button label={t('startInsight')} class="qm-primary" disabled={!snapshot||insights.busy} onclick={generate}/>{/if}
 {#if !shared.settings.notebook}<Button label={t('chooseNotebook')} onclick={()=>onsettings(true)}/>{/if}
 {/if}
 {#if error}<p role="alert">{t(error)}</p>{#if error==='aiNotConfigured'}<Button label={t('goAISettings')} onclick={()=>options.openAISettings()}/>{:else if !result&&!history}<Button label={t('retry')} onclick={prepare}/>{/if}{/if}
 {#if scopeOpen}<Dialog label={t('insightScope')} closeLabel={t('closeDialog')} {root} onclose={()=>scopeOpen=false}><Scope initial={scope} onclose={()=>scopeOpen=false} onapply={next=>{scope=next;scopeOpen=false;prepare();}}/></Dialog>{/if}
</section>
<style>.qm-insights{padding:0 12px 24px;box-sizing:border-box;overflow:auto}.qm-insight-section{display:block;background:var(--qm-surface);border-radius:12px;padding:16px;margin:12px 0}.qm-insight-section textarea{box-sizing:border-box;display:block;width:100%;margin-top:8px;background:var(--qm-surface);color:var(--qm-text);border:1px solid var(--qm-border);border-radius:8px;padding:12px;font:inherit}.qm-insight-actions{display:flex;flex-wrap:wrap;gap:8px}.qm-insight-explanation,.qm-insight-section time,:global(.qm-insight-history) small{color:var(--qm-text-secondary)}.qm-material{border-top:1px solid var(--qm-border);padding:12px 0}.qm-material p{white-space:pre-wrap;max-height:6em;overflow:auto}:global(.qm-insight-history){display:flex;flex-direction:column;min-height:64px;width:100%;align-items:flex-start}.qm-insight-body{white-space:normal}</style>
